{"page": {"kind": "quiz", "eyebrow": null, "headline": "随堂检验", "lead": null}, "brief": {"objective": "学生能判断给定场景下学习率调整策略是否正确", "keyClaim": "学习率过大导致发散，过小收敛慢，衰减和自适应方法可缓解", "misconception": "学习率越小越安全", "visualTask": "作答后能从解释看出判定链条", "evidencePolicy": "derived"}, "siblingPlan": [{"id": "bq", "type": "quiz", "role": "practice", "intent": "考察学习率过大/过小/合适的判断，以及衰减策略的选择", "size": "m"}]}
